def activate(self, branches, exclusive=False):
        """
        Activate branches

        Parameters
        ----------
        branches : str or list
            branch or list of branches to activate

        exclusive : bool, optional (default=False)
            if True deactivate the remaining branches
        """
        if not isinstance(branches, (list, tuple)):
            branches = [branches]
        for branch in branches:
            if branch not in self.branches:
                raise RuntimeError("Unknown branch %s" % branch)
        if exclusive:
            for branch in self.branches:
                if branch not in branches:
                    self.deactivate(branch)
        self.active_branches = self.active_branches.union(branches)

